theme.css:
/* Highlights by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero .ip-header { text-align:center; max-width:960px; margin:auto; align-self:center; }
.ip-title { text-transform:uppercase; letter-spacing:.075em; max-width:100%; font-size:clamp(var(--pager-title-min-size), calc(1rem + 3vw), var(--pager-title-size)); }
.ip-description { margin-inline:auto; }
.ip-hero .ip-navigation { justify-content:center; }
.page-blocks { width:min(100% - 32px, 960px); margin:auto; background:#ffffff; }
.ip-block { padding-block:48px; border-bottom:1px solid var(--pager-border); }
.ip-block .block-heading { text-align:center; text-transform:uppercase; font-size:1.25rem; letter-spacing:.08em; }
@media(max-width:760px) { .page-blocks { width:100%; } .ip-block { padding-block:32px; } }

.ip-hero:has(.ip-banner)::after { background:linear-gradient(#0009,#000b); }
.ip-hero:has(.ip-banner) .ip-description { color:#ffffff; opacity:1; }

.ip-description { opacity:1; }

.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
